package com.gathin.tvhome;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class SceneSchedulePolicyTest {
    private final String a="p-00000000-0000-0000-0000-000000000001",b="p-00000000-0000-0000-0000-000000000002";
    private void rejects(Runnable r){try{r.run();fail();}catch(IllegalArgumentException expected){}}
    @Test public void defaultsOffAndRoundTrip(){assertFalse(SceneSchedulePolicy.parse("").enabled);SceneSchedulePolicy.Spec s=new SceneSchedulePolicy.Spec(true,Arrays.asList(new SceneSchedulePolicy.Rule(31,1080,1380,a)));assertEquals(s.encode(),SceneSchedulePolicy.parse(s.encode()).encode());assertEquals(a,s.select(0,1080));assertEquals("",s.select(0,1380));assertEquals("",s.select(5,1200));}
    @Test public void midnightAndWeekWrapUseStartDay(){SceneSchedulePolicy.Rule r=new SceneSchedulePolicy.Rule(64,1380,60,a);assertTrue(r.matches(6,1439));assertTrue(r.matches(0,0));assertFalse(r.matches(0,60));assertFalse(r.matches(0,1380));}
    @Test public void overlappingWindowsAndInvalidFieldsRejected(){rejects(()->new SceneSchedulePolicy.Spec(true,Arrays.asList(new SceneSchedulePolicy.Rule(64,1380,60,a),new SceneSchedulePolicy.Rule(1,30,120,b))));rejects(()->new SceneSchedulePolicy.Rule(0,1,2,a));rejects(()->new SceneSchedulePolicy.Rule(1,0,1440,a));rejects(()->new SceneSchedulePolicy.Rule(1,1,1,a));rejects(()->new SceneSchedulePolicy.Rule(1,1,2,"../movie"));rejects(()->SceneSchedulePolicy.parse("v1|on|01,10,20,"+a));}
    @Test public void adjacentWindowsAreAllowedButMissingPlaylistAssetsAreNot(){SceneSchedulePolicy.Spec s=new SceneSchedulePolicy.Spec(true,Arrays.asList(new SceneSchedulePolicy.Rule(127,600,660,a),new SceneSchedulePolicy.Rule(127,660,720,b)));assertEquals(a,s.select(4,659));assertEquals(b,s.select(4,660));rejects(()->s.validatePlaylist(Collections.singletonList(a)));s.validatePlaylist(Arrays.asList(a,b));assertEquals("",s.select(4,720));}
    @Test public void disabledSchedulesAndDefensiveCopy(){List<SceneSchedulePolicy.Rule> rules=new ArrayList<>(Arrays.asList(new SceneSchedulePolicy.Rule(127,0,1,a)));SceneSchedulePolicy.Spec s=new SceneSchedulePolicy.Spec(false,rules);rules.clear();assertEquals(1,s.rules.size());assertEquals("",s.select(0,0));rejects(()->new SceneSchedulePolicy.Spec(true,Collections.emptyList()));assertTrue(SetupValues.KEYS.contains(SceneSchedules.KEY));}
    @Test public void recoveryOfOlderSetupsClearsScenesRatherThanInheritingCurrentRules(){Map<String,Object> values=new HashMap<>();values.put(WallpaperPlaylistChoice.KEY,new PlaylistPolicy.Spec(false,900,false,Collections.singletonList(b)).encode());SceneSchedules.validateReplacement(values);String scheduled=new SceneSchedulePolicy.Spec(true,Collections.singletonList(new SceneSchedulePolicy.Rule(127,0,1,a))).encode();values.put(SceneSchedules.KEY,scheduled);rejects(()->SceneSchedules.validateReplacement(values));values.put(WallpaperPlaylistChoice.KEY,new PlaylistPolicy.Spec(true,900,false,Arrays.asList(a,b)).encode());SceneSchedules.validateReplacement(values);SceneSchedules.validateReplacement(Collections.emptyMap());}
}
